function loadModule(specifier) {
    return import(specifier);
}
export function createDefaultInvalidationCallbacks(callbacks) {
    return {
        clearSSRModuleCache: () => {
            return loadModule("#veryfront/modules/react-loader/ssr-module-loader/cache/index.ts").then((m) => m.clearSSRModuleCache());
        },
        clearModulePathCache: () => {
            return loadModule("#veryfront/transforms/mdx/esm-module-loader/cache/index.ts").then((m) => m.clearModulePathCache());
        },
        invalidateModulePaths: (changedPaths) => {
            return loadModule("#veryfront/transforms/mdx/esm-module-loader/cache/index.ts").then((m) => m.invalidateModulePaths(changedPaths));
        },
        clearSSRModuleCacheForProject: (projectId) => {
            return loadModule("#veryfront/modules/react-loader/ssr-module-loader/cache/index.ts").then((m) => m.clearSSRModuleCacheForProject(projectId));
        },
        clearRouterDetectionCacheForProject: async (projectId) => {
            const module = await loadModule("#veryfront/rendering/router-detection.ts");
            module.clearRouterDetectionCacheForProject(projectId);
        },
        clearProjectDiscoveryCacheForProject: async (projectId) => {
            const module = await loadModule("#veryfront/server/handlers/request/api/project-discovery.ts");
            module.clearProjectDiscoveryCacheForProject(projectId);
        },
        clearSnippetCacheForProject: (projectSlug) => {
            return loadModule("#veryfront/rendering/snippet-renderer.ts").then((m) => m.clearSnippetCacheForProject(projectSlug));
        },
        clearRendererCacheForProject: async (projectId) => {
            const { clearRendererCacheForProject } = await loadModule("#veryfront/rendering/renderer.ts");
            return clearRendererCacheForProject(projectId);
        },
        ...callbacks,
    };
}
